dashboard.definition:
{
	"dataSources": {
		"ds_8U8hxie1": {
			"name": "sec_pos_self_signed_certs_spark",
			"options": {
				"query": "`corelight_idx` `corelight_evt_ssl` is_self_signed=\"yes\" is_dest_internal_ip=\"true\" sensor_name=$tkn_sensor_name|s$ \n| eventstats values(dest_ip) as destip by uid \n| timechart span=1h dc(dest_ip)",
				"queryParameters": {
					"earliest": "$tkn_time_restriction.earliest$",
					"latest": "$tkn_time_restriction.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_conn_spark_unencrypted": {
			"name": "sec_pos_spark_unencrypted",
			"options": {
				"query": "`corelight_idx` `corelight_etc_viz` sensor_name=$tkn_sensor_name|s$  viz_stat IN (\"C\", \"Cc\", \"C!\", \"cc\") \n| dedup uid\n\n| timechart span=1h count  by server_a",
				"queryParameters": {
					"earliest": "$tkn_time_restriction.earliest$",
					"latest": "$tkn_time_restriction.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_conn_telnet_traffic_inbound": {
			"name": "sec_pos_telnet_traffic_inbound",
			"options": {
				"enableSmartSources": true,
				"query": "`corelight_idx`   `corelight_evt_conn_all` id.resp_p=23 sensor_name=$tkn_sensor_name|s$  \n| stats count\n| eval formatted_count=if(count > 999,    \n      if(round(count/1000)*1000 == count, tostring(round(count/1000)) . \"K\",\n      if(count % 1000 <= 100, tostring(floor(count/1000)) . \"K\",\n      tostring(round(count/1000, 1)) . \"K\")), tostring(count))\n| fields formatted_count",
				"queryParameters": {
					"earliest": "$tkn_time_restriction.earliest$",
					"latest": "$tkn_time_restriction.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_conn_traffic_unencrypted": {
			"name": "soc_pos_unencrypted_traffic",
			"options": {
				"query": "`corelight_idx` `corelight_etc_viz` sensor_name=$tkn_sensor_name|s$ viz_stat IN (\"C\", \"Cc\", \"C!\", \"cc\") \n| dedup uid\n| stats count by server_a server_p\n\n | stats sum(count) as count\n | eval formatted_count=if(count > 999,\n    if(round(count/1000)*1000 == count, tostring(round(count/1000)) . \"K\", \n    if(count % 1000 <= 100, tostring(floor(count/1000)) . \"K\", \n    tostring(round(count/1000, 1)) . \"K\")),\n    tostring(count))\n| fields formatted_count",
				"queryParameters": {
					"earliest": "$tkn_time_restriction.earliest$",
					"latest": "$tkn_time_restriction.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_conn_unencrypted_protocols": {
			"name": "sec_pos_top_unencrypted_protocols",
			"options": {
				"query": "`corelight_idx` `corelight_evt_conn_all`  sensor_name=$tkn_sensor_name|s$ NOT service IN (ssl, tls, dns, \"ssl,http\", \"http,ssl\") service=*\n| timechart span=1h count as \"Unencrypted Traffic Volume\" by service limit=10 useother=false",
				"queryParameters": {
					"earliest": "$tkn_time_restriction.earliest$",
					"latest": "$tkn_time_restriction.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_dns_base": {
			"name": "sec_pos_dns_base",
			"options": {
				"enableSmartSources": true,
				"query": "`corelight_idx` `corelight_evt_dns` sensor_name=$tkn_sensor_name|s$| iplocation dest_ip | eval Country = coalesce(Country, \"No Country\")\n| fields rcode_name, Country, qtype_name, failed_q, dest_ip, dest_port, lat, lon, is_dest_internal_ip",
				"queryParameters": {
					"earliest": "$tkn_time_restriction.earliest$",
					"latest": "$tkn_time_restriction.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_dns_countries_response": {
			"name": "soc_pos_dns_countries_response",
			"options": {
				"extend": "ds_dns_base",
				"query": "| stats count as Count by Country| sort - Count"
			},
			"type": "ds.chain"
		},
		"ds_dns_failed_dns_queries": {
			"name": "sec_pos_failed_dns_queries",
			"options": {
				"extend": "ds_dns_base",
				"query": "| search rcode_name IN (SERVFAIL, REFUSED, FORMERR ,NOTIMP ,NOTAUTH)\n| timechart count(rcode_name) as dns_fails"
			},
			"type": "ds.chain"
		},
		"ds_dns_failed_query": {
			"name": "sec_pos_dns_qtypes",
			"options": {
				"extend": "ds_dns_base",
				"query": "|search qtype_name IN (\"AXFR\", \"IXFR\", \"ANY\", \"TXT\")\n| timechart span=1h count as failed_q\n| eval failed_q = if(failed_q>1000,tostring(round(failed_q/1000)).\"K\",failed_q)"
			},
			"type": "ds.chain"
		},
		"ds_dns_known_dns_svr_int": {
			"name": "sec_post_known_dns_svr_int",
			"options": {
				"extend": "ds_dns_base",
				"query": "| search dest_ip=* dest_port IN (53, 5353) \n| where is_dest_internal_ip=\"true\"\n| stats dc(dest_ip) as NumberOfInternalDnsServers"
			},
			"type": "ds.chain"
		},
		"ds_dns_location": {
			"name": "sec_pos_dns_location",
			"options": {
				"extend": "ds_dns_base",
				"query": "| stats count by lat, lon, Country| eval count=if(isnull(count), 0, count)| where lat!=0 OR lon!=0"
			},
			"type": "ds.chain"
		},
		"ds_dns_nxdomains_tc_cnt": {
			"name": "sec_pos_dns_nxdomains_tc_cnt",
			"options": {
				"extend": "ds_dns_base",
				"query": "| search NOT rcode_name IN (NXDOMAIN, \"NO ERROR\")\n| timechart count as failed_q"
			},
			"type": "ds.chain"
		},
		"ds_dns_queries_spark": {
			"name": "sec_pos_dns_queries_spark",
			"options": {
				"extend": "ds_dns_base",
				"query": "| search  rcode_name IN (SERVFAIL, REFUSED, FORMERR, NOTIMP, NOTAUTH)\n| timechart span=1h count(rcode_name)"
			},
			"type": "ds.chain"
		},
		"ds_dns_unusual_q_types_spark": {
			"name": "sec_pos_DNS_unusual_qtypes_sprk",
			"options": {
				"extend": "ds_dns_base",
				"query": "|search qtype_name IN (\"AXFR\", \"IXFR\", \"ANY\", \"TXT\")| timechart span=1h count as \"Unusual QTypes\""
			},
			"type": "ds.chain"
		},
		"ds_ftp_unencrypted_ftp_count": {
			"name": "sec_pos_unencrypted_ftp_count",
			"options": {
				"query": "`corelight_idx` `corelight_evt_ftp` sensor_name=\"*\"\n| dedup uid\n| stats count\n| eval formatted_count=if(count > 999,\n    if(round(count/1000)*1000 == count, tostring(round(count/1000)) . \"K\",\n    if(count % 1000 <= 100, tostring(floor(count/1000)) . \"K\",\n    tostring(round(count/1000, 1)) . \"K\")),\n    tostring(count))\n| fields formatted_count",
				"queryParameters": {
					"earliest": "$tkn_time_restriction.earliest$",
					"latest": "$tkn_time_restriction.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_lookup_corelight_systems": {
			"name": "corelight_system_csv",
			"options": {
				"query": "|inputlookup corelight_systems"
			},
			"type": "ds.search"
		},
		"ds_rdp_authentications": {
			"name": "sec_pos_rdp_authentications",
			"options": {
				"query": "`corelight_idx` `corelight_evt_rdp` auth_success=* sensor_name=$tkn_sensor_name|s$  | eval auth_result = case(auth_success==\"true\",\"Success\", auth_success==\"false\",\"Failure\") | timechart span=1h count by auth_result cont=true",
				"queryParameters": {
					"earliest": "$tkn_time_restriction.earliest$",
					"latest": "$tkn_time_restriction.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_smbv1_traffic": {
			"name": "sec_pos_smbv1_traffic",
			"options": {
				"query": "`corelight_idx` `corelight_smb` sensor_name=\"*\"  \n| eval smb_version = case('id.resp_p' == 139, \"SMBv1\", 'id.resp_p' == 445, \"SMBv2_or_SMBv3\", true(), \"unknown\")\n| stats count\n| eval formatted_count=if(count > 999, if(round(count/1000)*1000 == count, tostring(round(count/1000)) . \"K\", if(count % 1000 <= 100, tostring(floor(count/1000)) . \"K\",    tostring(round(count/1000, 1)) . \"K\")),    tostring(count))\n| fields formatted_count",
				"queryParameters": {
					"earliest": "$tkn_time_restriction.earliest$",
					"latest": "$tkn_time_restriction.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_ssl_base_chain": {
			"name": "sec_pos_ssl_base_chain",
			"options": {
				"query": "`corelight_idx` `corelight_evt_ssl` sensor_name=$tkn_sensor_name|s$ \n| eval src_internal=if(isnull(is_src_internal_ip) OR is_src_internal_ip=\"false\", \"External\", \"Internal\"), dest_internal=if(isnull(is_dest_internal_ip) OR is_dest_internal_ip=\"false\", \"External\", \"Internal\"), connection_type=case(    src_internal=\"Internal\" AND dest_internal=\"External\", \"Internal to External\",    src_internal=\"External\" AND dest_internal=\"Internal\", \"External to Internal\",    src_internal=\"Internal\" AND dest_internal=\"Internal\", \"Internal to Internal\",    src_internal=\"External\" AND dest_internal=\"External\", \"External to External\"  ) \n| fields version_status, version, is_self_signed",
				"queryParameters": {
					"earliest": "$tkn_time_restriction.earliest$",
					"latest": "$tkn_time_restriction.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_ssl_encrypted_over_time": {
			"name": "sec_post_encrypted_over_time",
			"options": {
				"extend": "ds_ssl_base_chain",
				"query": "| timechart span=1h count as \"Encrypted Traffic Volume\""
			},
			"type": "ds.chain"
		},
		"ds_ssl_int_ext_cert": {
			"name": "ds_eJEaVdZW",
			"options": {
				"legendDisplay": "off",
				"seriesColors": [
					"#00AB49",
					"#00CDAF"
				],
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide"
			},
			"type": "splunk.column"
		},
		"ds_ssl_selfsigned_certs_dc_dest": {
			"name": "sec_post_selfsigned_certs_dc_dest",
			"options": {
				"extend": "ds_ssl_base_chain",
				"query": "| timechart span=15m dc(dest_ip) as unique_self_signed_certs"
			},
			"type": "ds.chain"
		},
		"ds_ssl_tls_versions": {
			"name": "sec_pos_tls_versions",
			"options": {
				"extend": "ds_ssl_base_chain",
				"query": "| eval version_status=case(    version==\"TLSv13\", \"Most Secure\",    version==\"TLSv12\", \"Secure\",    version==\"DTLSv12\", \"Secure\",     version==\"unknown-64282\", \"Unknown\",    true(), \"Old Version\"  )| stats count by version_status| sort - count"
			},
			"type": "ds.chain"
		},
		"ds_vpn_base": {
			"name": "sec_pos_vpn_base",
			"options": {
				"query": "`corelight_idx` `corelight_evt_vpn` sensor_name=$tkn_sensor_name|s$\n| iplocation dest_ip| eval location = mvjoin(mvappend(location, coalesce(Country, \"No Country\"), coalesce(City, \"No City\")), \", \")\n| fields dest_ip, src_ip, Country, City, lat, lon, is_dest_internal_ip, location",
				"queryParameters": {
					"earliest": "$tkn_time_restriction.earliest$",
					"latest": "$tkn_time_restriction.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_vpn_by_country_base": {
			"name": "sec_pos_vpn_by_country_base",
			"options": {
				"extend": "ds_vpn_base",
				"query": "| stats count by dest_ip, Country, City\n| top Country\n| sort - count"
			},
			"type": "ds.chain"
		},
		"ds_vpn_outbound_conn": {
			"name": "sec_pos_vpn_outbound_conn",
			"options": {
				"extend": "ds_vpn_base",
				"query": "| where is_dest_internal_ip = \"false\"\n| timechart span=1h count"
			},
			"type": "ds.chain"
		},
		"ds_x509_base": {
			"name": "sec_post_x509_base",
			"options": {
				"query": "`corelight_idx` `corelight_evt_x509`  sensor_name=$tkn_sensor_name|s$\n| eval not_valid_after_epoch = strptime('certificate.not_valid_after', \"%Y-%m-%dT%H:%M:%S.000000Z\"), current_time_epoch = now(), days_to_expire = round((not_valid_after_epoch - current_time_epoch) / 86400, 0), key_length=tonumber('certificate.key_length')\n| fields ssl_hash, not_valid_after_epoch, key_length, current_time_epoch, days_to_expire",
				"queryParameters": {
					"earliest": "$tkn_time_restriction.earliest$",
					"latest": "$tkn_time_restriction.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_x509_certs_about_expire": {
			"name": "sec_pos_certs_about_exp",
			"options": {
				"extend": "ds_x509_base",
				"query": "| where days_to_expire > 0 AND days_to_expire <= 15| stats dc(ssl_hash) as \"Distinct Certs\""
			},
			"type": "ds.chain"
		},
		"ds_x509_certs_short_key_len": {
			"name": "sec_pos_certs_short_key_lengths",
			"options": {
				"enableSmartSources": true,
				"extend": "ds_x509_base",
				"query": "| where key_length < 2048\n| stats dc(ssl_hash)"
			},
			"type": "ds.chain"
		},
		"ds_x509_selfsigned_certs": {
			"name": "sec_post_selfsigned_certs",
			"options": {
				"query": "`corelight_idx` `corelight_evt_ssl` is_self_signed=\"yes\" is_dest_internal_ip=\"true\" sensor_name=$tkn_sensor_name|s$ \n| dedup dest_ip\n| eventstats values(ssl_subject_common_name) as destip\n| stats dc(ssl_subject_common_name)",
				"queryParameters": {
					"earliest": "$tkn_time_restriction.earliest$",
					"latest": "$tkn_time_restriction.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_x509_spark_cert_keys": {
			"name": "sec_pos_spark_cert_keys",
			"options": {
				"extend": "ds_x509_base",
				"query": "| where key_length < 2048\n| timechart span=1h dc(ssl_hash)"
			},
			"type": "ds.chain"
		},
		"ds_idcmUaym": {
			"type": "ds.search",
			"options": {
				"query": "`corelight_idx` `corelight_evt_aggregations`  sensor_name=\"$tkn_sensor_name$\" \n| eval sid = mvappend(sid, 'sid{}')\n| lookup corelight_alert_aggregations sid OUTPUT sid as lookup_sid impact_score category technique_number cve_number cve_creation_date\n| search lookup_sid=*\n| eval is_internal = if(is_dest_internal_ip == \"true\", 1, 0)\n| stats \n    dc(did) as Detections,\n    count(sid) as Alerts,\n    dc(uid) as Impacted_UIDs,\n    last(cve_creation_date) as oldest_cve,\n    count(eval(is_internal=1)) as Impacted_Int_Hosts,\n    dc(technique_number) as Mitre_Techniques,\n    max(impact_score) as Highest_Score,\n    mode(category) as Most_Seen_Cat,\n    avg(impact_score) as Average_Impact_Score,\n    count(eval(isnotnull(cve_number))) as Detections_with_CVEs\n| eval oldest_cve = strftime(strptime(oldest_cve, \"%Y-%m-%d %H:%M:%S\"), \"%Y-%m-%d\")\n| appendcols [\n    search `corelight_idx` `corelight_st_notice` note!=\"Intel*\" sensor_name=\"$tkn_sensor_name$\" id.orig_h=*\n| dedup uid\n| rex field=note \"^(?P<attack_type>[^\\s]+)\"\n| stats distinct_count(attack_type) as Unique_Notes, \n        count(eval(attack_type LIKE \"ATTACK::%\")) as ATTACK_Types,\n        count as Notice_Count\n]\n| appendcols [\n    search `corelight_idx` `corelight_st_suricata` sensor_name=\"$tkn_sensor_name$\" \n    | dedup uid\n    | stats count as Suricata_Count\n]\n| appendcols [\n    search `corelight_idx` `corelight_st_notice` sensor_name=\"$tkn_sensor_name$\" note=\"Intel*\"\n    | stats count as Intel_Count\n]\n| appendcols [\n    search `corelight_idx` `corelight_st_notice` sensor_name=\"$tkn_sensor_name$\" note IN (\"SSL::Certificate_Expired\", \"SSL::Invalid_Server_Cert\", \"SSL::Old_Version\") \n    | stats count as SSL_Issues_Count\n]\n| appendcols [\n    search `corelight_idx` `corelight_st_notice` sensor_name=\"$tkn_sensor_name$\" note=\"MeterpreterDetection::Meterpreter_Detected\"\n    | stats count as Meterpreter_Count\n]\n| appendcols [\n    search `corelight_idx` `corelight_st_intel` sensor_name=\"$tkn_sensor_name$\" \n    | stats \n        count as TotalAlerts,\n        dc(seen.indicator) as UniqueIndicators,\n        dc(id.orig_h) as UniqueSourceIPs,\n        dc(id.resp_h) as UniqueDestIPs,\n        dc(seen.indicator_type) as UniqueIndicatorTypes,\n        dc(seen.where) as UniqueDiscoveryLocations,\n        dc(sources) as UniqueSources,\n        dc(matched{}) as MatchedTypes\n    | eval \n        AvgAlertsPerIndicator = round(TotalAlerts / UniqueIndicators, 2),\n        AvgAlertsPerSourceIP = round(TotalAlerts / UniqueSourceIPs, 2)\n]\n\n| fields Detections Alerts Impacted_UIDs oldest_cve Impacted_Int_Hosts Mitre_Techniques Highest_Score Most_Seen_Cat Average_Impact_Score Intel_Count Detections_with_CVEs Notice_Count ATTACK_Types Unique_Notes Suricata_Count SSL_Issues_Count Meterpreter_Count TotalAlerts UniqueIndicators UniqueSourceIPs UniqueDestIPs UniqueIndicatorTypes UniqueDiscoveryLocations UniqueSources AvgAlertsPerIndicator AvgAlertsPerSourceIP MatchedTypes\n| `dynamic_format_high_counts`",
				"queryParameters": {
					"earliest": "$tkn_time_restriction.earliest$",
					"latest": "$tkn_time_restriction.latest$"
				},
				"enableSmartSources": true
			},
			"name": "sec_pos_alerts_trends_counts"
		},
		"ds_ie94U28K": {
			"type": "ds.search",
			"options": {
				"query": "`corelight_idx` `corelight_evt_aggregations`\n| bin _time span=1h\n| timechart count as detections",
				"queryParameters": {
					"earliest": "$tkn_time_restriction.earliest$",
					"latest": "$tkn_time_restriction.latest$"
				}
			},
			"name": "sec_pos_spark_suri_aggregations"
		},
		"ds_byFwvd9F": {
			"type": "ds.chain",
			"options": {
				"enableSmartSources": true,
				"extend": "ds_idcmUaym",
				"query": "| eval is_valid_cve=if(cve_number!=\"\" AND cve_number!=\"N/A\", 1, 0)\n| eventstats count(eval(is_valid_cve=1)) as cve_count\n| stats dc(technique_number) as tech_number_count, max(impact_score) as highest_score, values(cve_count) as cve_number\n| appendcols [\n    search `corelight_idx` `corelight_st_suricata` sensor_name=\"$tkn_sensor_name$\" \n    | eval is_internal=if(is_dest_internal_ip=\"true\", 1, 0)\n    | stats count as total_alerts, dc(alert.signature_id) as distinct_signature_count, dc(id.orig_h) as unique_source_ips, dc(eval(if(is_internal=1, 'id.resp_h', null))) as unique_internal_dest, dc(id.resp_h) as unique_destination_ips\n    ]\n    | fields *\n    | `dynamic_format_high_counts`"
			},
			"name": "soc_tech_number_count"
		},
		"ds_p2r2ozOo": {
			"type": "ds.search",
			"options": {
				"query": "`corelight_idx` `corelight_st_suricata`\n| bin _time span=1h\n| timechart count as detections\n| bin _time span=1h\n| stats count as notealerts by _time",
				"queryParameters": {
					"earliest": "$tkn_time_restriction.earliest$",
					"latest": "$tkn_time_restriction.latest$"
				}
			},
			"name": "sec_pos_spark_surialertsonly"
		},
		"ds_8C6XSy9q": {
			"type": "ds.search",
			"options": {
				"query": "`corelight_idx` `corelight_st_notice`sensor_name=\"$tkn_sensor_name$\" note!=Intel*\n| timechart span=1h dc(note) as uniquenote",
				"queryParameters": {
					"earliest": "$tkn_time_restriction.earliest$",
					"latest": "$tkn_time_restriction.latest$"
				}
			},
			"name": "sec_pos_spark_notices_only"
		},
		"ds_7mGmfut0": {
			"type": "ds.search",
			"options": {
				"query": "`corelight_idx` `corelight_st_intel` sensor_name=\"$tkn_sensor_name$\"\n| bin _time span=1h\n| stats count as intelalerts by _time",
				"queryParameters": {
					"earliest": "$tkn_time_restriction.earliest$",
					"latest": "$tkn_time_restriction.latest$"
				}
			},
			"name": "sec_pos_spark_intel"
		}
	},
	"defaults": {
		"dataSources": {
			"ds.search": {
				"options": {
					"queryParameters": {
						"earliest": "$tkn_time_restriction.earliest$",
						"latest": "$tkn_time_restriction.latest$"
					}
				}
			}
		}
	},
	"description": "Current Security Posture with Corelight",
	"inputs": {
		"input_sensor_name": {
			"dataSources": {
				"primary": "ds_lookup_corelight_systems"
			},
			"options": {
				"defaultValue": "*",
				"items": [
					{
						"label": "All",
						"value": "*"
					}
				],
				"token": "tkn_sensor_name"
			},
			"title": "Sensor",
			"type": "input.dropdown"
		},
		"input_time_restriction": {
			"options": {
				"defaultValue": "-24h@h,now",
				"token": "tkn_time_restriction"
			},
			"title": "Global Time Restriction",
			"type": "input.timerange"
		}
	},
	"layout": {
		"globalInputs": [
			"input_time_restriction",
			"input_sensor_name"
		],
		"options": {
			"backgroundColor": "transparent",
